function openApplicationDb(){return new Promise((resolve,reject)=>{const request=indexedDB.open('zwconnect-applications',1);request.onupgradeneeded=()=>request.result.createObjectStore('applications',{keyPath:'id'});request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)})}
async function saveApplicationForAdmin(application,file){const db=await openApplicationDb();await new Promise((resolve,reject)=>{const tx=db.transaction('applications','readwrite');tx.objectStore('applications').put({...application,proofFile:file});tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});db.close()}
