const $=s=>document.querySelector(s); const $$=s=>[...document.querySelectorAll(s)];
function escapeHtml(value){return String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]))}
function databaseShopId(shop){if(shop?.dbId)return shop.dbId;try{return JSON.parse(localStorage.getItem('zwconnect-shop-database-ids')||'{}')[shop?.name]||null}catch{return null}}
function salesModeLabel(mode){return mode==='wholesale'?'Wholesale only':mode==='hybrid'?'Wholesale & retail':'Retail only'}
function saleUnitOptions(shop){return shop.salesMode==='wholesale'?'<option value="case">Full case / wholesale</option>':shop.salesMode==='retail'?'<option value="unit">Singular unit / retail</option>':'<option value="unit">Singular unit / retail</option><option value="case">Full case / wholesale</option>'}
function productPriceMarkup(shop,product){const unit=`<span><small>Retail unit</small><strong>US$ ${product.price.toFixed(2)}</strong></span>`,casePrice=`<span><small>Wholesale case of ${product.caseSize}</small><strong>US$ ${product.casePrice.toFixed(2)}</strong></span>`;return `<div class="package-prices ${shop.salesMode}">${shop.salesMode==='wholesale'?casePrice:shop.salesMode==='retail'?unit:unit+casePrice}</div>`}
function renderCouriers(){const city=state.city?.name;const list=approvedCouriers.filter(c=>!city||c.city===city);$('#courierPublicGrid').innerHTML=(list.length?list:approvedCouriers).map(c=>`<article class="courier-public-card"><div class="courier-avatar"><i data-lucide="bike"></i></div><div><span class="status-pill ${c.available?'approved':''}">${c.available?'Available':'Unavailable'}</span><h3>${c.name}</h3><p>${c.rider} • ${c.city}</p><div class="courier-rate"><strong>From US$ ${c.base.toFixed(2)}</strong><small>${c.rateType==='location'?'Location pricing':`+ US$ ${c.perKm.toFixed(2)}/km after ${c.included} km`} • up to ${c.max} km</small></div><footer><span>★ ${c.rating} • Admin approved</span><a href="tel:${c.phone.replace(/\s/g,'')}">${c.phone}</a></footer></div></article>`).join('');showOnly('couriersPage');icons()}
function paymentMethodsFor(shop){return paymentMethods.filter(x=>x.shopId===shop.id)}
function openPayment(shopId,sku){const shop=shops.find(s=>s.id===shopId),product=shop?.products.find(p=>p.sku===sku);if(!shop||!product)return;state.paymentShop=shop;state.paymentProduct=product;const form=$('#paymentModal form');form.dataset.shop=shop.id;form.dataset.sku=product.sku;form.querySelector('[name="saleUnit"]').innerHTML=saleUnitOptions(shop);form.querySelector('[name="paymentMethod"]').innerHTML=paymentMethodsFor(shop).map(m=>`<option value="${m.id}">${m.name} — ${m.number}</option>`).join('')||'<option value="demo-ecocash">EcoCash — details shown after submission</option>';$('#paymentProductSummary').textContent=`${product.name} from ${shop.name}`;updateCustomerOrderTotal();openModal('paymentModal')}
function updateCustomerOrderTotal(){const form=$('#paymentModal form'),product=state.paymentProduct;if(!form||!product)return;const qty=Math.max(1,Number(form.quantity.value)||1),isCase=form.saleUnit.value==='case',price=isCase?product.casePrice:product.price;$('#customerOrderTotal').textContent=`US$ ${(qty*price).toFixed(2)}`}
function renderPaymentSettings(){const methods=paymentMethodsFor(shops[0]);$('#portalContent').innerHTML=`<div class="payment-owner-grid"><section class="portal-panel"><div class="panel-head"><div><h2>Company payment details</h2><p>Customers see only enabled methods when submitting an order.</p></div><span class="status-pill approved">Owner only</span></div><form id="paymentMethodForm" class="payment-method-form"><label>Method<select name="type"><option value="ecocash">EcoCash</option><option value="onemoney">OneMoney</option><option value="bank_transfer">Bank transfer</option><option value="cash_on_delivery">Cash on delivery</option></select></label><label>Display name<input name="name" required placeholder="e.g. EcoCash merchant"></label><label>Account name<input name="account" required></label><label>Account / merchant number<input name="number" required></label><label class="span-two">Customer instructions<textarea name="instructions" placeholder="Reference or narration instructions"></textarea></label><button class="primary-button" type="submit">Add payment method</button></form><div class="payment-method-list">${methods.map((m,i)=>`<div><span><i data-lucide="${m.type==='bank_transfer'?'landmark':'smartphone'}"></i></span><div><strong>${m.name}</strong><small>${m.account} • ${m.number}</small><p>${m.instructions}</p></div><button data-remove-payment-method="${i}">Disable</button></div>`).join('')}</div></section><section class="portal-panel"><div class="panel-head"><div><h2>Posting rule</h2><p>Confirmation is a single database transaction.</p></div></div><div class="ledger-flow"><span>Payment submitted</span><i data-lucide="lock-keyhole"></i><span>Owner confirms</span><i data-lucide="book-check"></i><span>Sale + ledger + stock</span></div><div class="permission-note"><strong>No premature stock movement:</strong> pending or rejected payments never change inventory. Confirmation creates the sale, deducts base units, records the product movement, posts the customer payment and platform fee ledger entries, then opens delivery if requested.</div></section></div>`;icons()}
function renderPaymentConfirmations(){if(window.ZWCart?.renderOwnerConfirmations)return window.ZWCart.renderOwnerConfirmations();const pending=customerPayments.filter(p=>p.status==='pending');$('#portalContent').innerHTML=`<div class="metric-grid">${metric('clock-3','Awaiting confirmation',pending.length)}${metric('banknote','Pending value',`US$ ${pending.reduce((n,p)=>n+p.amount,0).toFixed(2)}`)}${metric('bike','Delivery requests',pending.filter(p=>p.delivery).length)}${metric('book-check','Ledger posting','Automatic')}</div><section class="portal-panel"><div class="panel-head"><div><h2>Customer payment confirmations</h2><p>Match the reference against your company account before approving.</p></div><span class="status-pill">Owner only</span></div></section>`;icons()}
function updateSalePreview(){const form=$('#saleForm');if(!form)return;const shop=shops[0],product=shop.products.find(p=>p.sku===form.sku.value);if(!product)return;const saleUnit=form.saleUnit.value,quantity=Math.max(1,Number(form.quantity.value)||1),isCase=saleUnit==='case',baseQuantity=quantity*(isCase?product.caseSize:1),price=isCase?product.casePrice:product.price,max=Math.floor(product.quantity/(isCase?product.caseSize:1));form.quantity.max=String(Math.max(0,max));$('#saleQuantityHint').textContent=isCase?`${product.caseSize} units per case • ${max} cases available`:`${product.quantity} singular units available`;$('#salePackageLabel').textContent=`${quantity} ${isCase?(quantity===1?'case':'cases'):(quantity===1?'singular unit':'singular units')} • ${baseQuantity} unit${baseQuantity===1?'':'s'} deducted`;$('#saleTotal').textContent=`US$ ${(price*quantity).toFixed(2)}`}
async function restorePendingLocalState(){if(state.localStateRestored)return;state.localStateRestored=true;try{for(const movement of await inventoryRecords())applyLocalMovement(movement.shopId,movement.sku,movement.delta)}catch{}try{for(const action of await window.ZWOffline.list()){if(action.type==='sale.create'){const shop=shops.find(s=>s.id===action.payload.localShopId)||shops[0];for(const item of action.payload.items||[]){const baseQuantity=Number(item.base_quantity||item.quantity*(item.sale_unit==='case'?item.units_per_case||1:1));applyLocalMovement(shop.id,item.sku,-baseQuantity)}}if(action.type==='customer_order.review'&&action.payload.approve){const items=action.payload.items?.length?action.payload.items:[{sku:action.payload.sku,base_quantity:action.payload.baseQuantity}];for(const item of items)if(item.sku)applyLocalMovement(action.payload.localShopId||'shop-1',item.sku,-Number(item.base_quantity||0))}if(action.type==='worker.invite'&&!workers.some(w=>w.email.toLowerCase()===String(action.payload.email).toLowerCase()))workers.push({name:action.payload.name,email:action.payload.email,job:String(action.payload.job).replaceAll('_',' ').replace(/^./,c=>c.toUpperCase()),status:'Offline queued'})}}catch{}}
async function hydrateProductsFromSupabase(){if(!window.zwconnectSupabase||!navigator.onLine)return;for(const shop of shops){const shopId=databaseShopId(shop);if(!shopId)continue;const {data:shopRow}=await window.zwconnectSupabase.from('shops').select('sales_mode').eq('id',shopId).maybeSingle();if(shopRow?.sales_mode)shop.salesMode=shopRow.sales_mode;const {data,error}=await window.zwconnectSupabase.from('products').select('sku,price,quantity,case_size,case_price,allow_case_sales').eq('shop_id',shopId);if(!error)(data||[]).forEach(row=>{const product=shop.products.find(p=>p.sku===row.sku);if(product){product.price=Number(row.price);product.quantity=Number(row.quantity);product.caseSize=Number(row.case_size||1);product.casePrice=Number(row.case_price||row.price*row.case_size);product.allowCase=row.allow_case_sales!==false;product.stock=product.quantity===0?'Out of stock':product.quantity<=5?'Low stock':'In stock'}});const {data:methods}=await window.zwconnectSupabase.from('shop_payment_methods').select('id,method_type,display_name,account_name,account_number,instructions').eq('shop_id',shopId).eq('enabled',true);(methods||[]).forEach(row=>{if(!paymentMethods.some(m=>m.id===row.id))paymentMethods.push({id:row.id,shopId:shop.id,type:row.method_type,name:row.display_name,account:row.account_name,number:row.account_number,instructions:row.instructions||''})})}}
function icons(){if(window.lucide)lucide.createIcons()}
function profileById(id){return profiles.find(p=>p.id===id)}
function distance(a,b){const r=6371,dLat=(b.lat-a.lat)*Math.PI/180,dLng=(b.lng-a.lng)*Math.PI/180,la1=a.lat*Math.PI/180,la2=b.lat*Math.PI/180;const x=Math.sin(dLat/2)**2+Math.cos(la1)*Math.cos(la2)*Math.sin(dLng/2)**2;return r*2*Math.atan2(Math.sqrt(x),Math.sqrt(1-x))}
function shopDistance(shop){return state.userLocation?distance(state.userLocation,shop):null}
function showToast(text,icon='circle-check'){const toast=$('#toast');toast.innerHTML=`<i data-lucide="${icon}"></i><span>${text}</span>`;toast.classList.add('show');icons();clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>toast.classList.remove('show'),3000)}
const inventorySync={auto:localStorage.getItem('zwconnect-auto-sync')!=='false',syncing:false,lastSync:localStorage.getItem('zwconnect-last-sync')||'',history:[]};
const inventoryChannel='BroadcastChannel' in window?new BroadcastChannel('zwconnect-inventory'):null;
function openInventoryDb(){return new Promise((resolve,reject)=>{const request=indexedDB.open('zwconnect-inventory',1);request.onupgradeneeded=()=>request.result.createObjectStore('movements',{keyPath:'id'});request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)})}
async function allInventoryRecords(){const db=await openInventoryDb(),records=await new Promise((resolve,reject)=>{const request=db.transaction('movements').objectStore('movements').getAll();request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)});db.close();return records}
async function inventoryRecords(){const identity=window.ZWOffline?.identity()||{},records=await allInventoryRecords();return records.filter(record=>record.actorId&&identity.userId===record.actorId&&(!record.shopUuid||!identity.shopId||record.shopUuid===identity.shopId))}
async function saveMovement(record){const db=await openInventoryDb();await new Promise((resolve,reject)=>{const tx=db.transaction('movements','readwrite');tx.objectStore('movements').put(record);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});db.close()}
async function removeMovement(id){const db=await openInventoryDb();await new Promise((resolve,reject)=>{const tx=db.transaction('movements','readwrite');tx.objectStore('movements').delete(id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});db.close()}
function applyLocalMovement(shopId,sku,delta){const shop=shops.find(s=>s.id===shopId),product=shop?.products.find(p=>p.sku===sku);if(!product)return null;product.quantity=Math.max(0,Number(product.quantity||0)+Number(delta));product.stock=product.quantity===0?'Out of stock':product.quantity<=5?'Low stock':'In stock';return product}
async function updateSyncStatus(){let inventoryPending=0,inventoryLocked=0,actionStatus={pending:0,syncing:false,failed:0,locked:0};try{const own=await inventoryRecords(),all=await allInventoryRecords();inventoryPending=own.length;inventoryLocked=Math.max(0,all.length-own.length)}catch{}try{actionStatus=await window.ZWOffline?.status()||actionStatus}catch{}const pending=inventoryPending+actionStatus.pending,locked=inventoryLocked+(actionStatus.locked||0),button=$('#syncStatusButton');if(!button)return;const online=navigator.onLine,isSyncing=inventorySync.syncing||actionStatus.syncing,needsCloud=online&&pending&&!window.zwconnectSupabase;button.className=`sync-status ${!online?'offline':isSyncing?'syncing':actionStatus.failed?'offline':'online'}`;$('#syncStatusLabel').textContent=!online?'Working offline':isSyncing?'Syncing changes…':needsCloud?'Cloud connection needed':pending?'Ready to sync':locked?'Other account data locked':'All changes synced';$('#syncPendingLabel').textContent=locked?`${pending} pending • ${locked} locked`:`${pending} pending`;button.querySelector('i')?.classList.toggle('spin',isSyncing);icons()}
async function queueProductMovement(shopId,sku,delta,reason){const product=applyLocalMovement(shopId,sku,delta);if(!product)return;const identity=window.ZWOffline?.identity()||{},movement={id:crypto.randomUUID(),shopId,shopUuid:databaseShopId(shops.find(s=>s.id===shopId))||identity.shopId||null,actorId:identity.userId||null,sku,delta:Number(delta),reason,occurredAt:new Date().toISOString(),deviceId:identity.deviceId||localStorage.getItem('zwconnect-device-id')||crypto.randomUUID(),status:identity.userId?'pending':'blocked'};localStorage.setItem('zwconnect-device-id',movement.deviceId);await saveMovement(movement);inventorySync.history.unshift({...movement,product:product.name});inventoryChannel?.postMessage({shopId,sku,quantity:product.quantity,stock:product.stock,actorId:movement.actorId});await updateSyncStatus();showToast(identity.userId?(navigator.onLine?'Stock updated locally and queued for sync':'Offline change saved safely for this account'):'Change saved but locked until the original worker signs in',identity.userId?(navigator.onLine?'refresh-cw':'cloud-off'):'lock-keyhole');if(navigator.onLine&&inventorySync.auto&&identity.userId)flushInventoryQueue();if(state.portalTab==='sync')renderSyncCenter()}
async function flushInventoryQueue(){if(inventorySync.syncing||!navigator.onLine)return;const records=await inventoryRecords();if(!records.length){updateSyncStatus();return}if(!window.zwconnectSupabase)return updateSyncStatus();const {data:userData,error:userError}=await window.zwconnectSupabase.auth.getUser();const user=userData?.user;if(userError||!user)return updateSyncStatus();inventorySync.syncing=true;await updateSyncStatus();for(const movement of records){if(movement.actorId!==user.id)continue;try{const {error}=await window.zwconnectSupabase.rpc('apply_product_movement',{client_event_uuid:movement.id,target_product:movement.productId||null,target_shop:movement.shopUuid||null,target_sku:movement.sku,quantity_delta:movement.delta,movement_reason:movement.reason,occurred_at:movement.occurredAt,source_device:movement.deviceId});if(error)throw error;await removeMovement(movement.id);const history=inventorySync.history.find(x=>x.id===movement.id);if(history)history.status='synced'}catch{break}}inventorySync.syncing=false;inventorySync.lastSync=new Date().toISOString();localStorage.setItem('zwconnect-last-sync',inventorySync.lastSync);await updateSyncStatus();if(state.portalTab==='sync')renderSyncCenter();showToast((await inventoryRecords()).length?'This account still has changes waiting to sync':'This account’s offline changes synced successfully',(await inventoryRecords()).length?'cloud-off':'cloud-check')}
function setupRealtimeProducts(){if(!window.zwconnectSupabase)return;window.zwconnectSupabase.channel('zwconnect-product-stock').on('postgres_changes',{event:'UPDATE',schema:'public',table:'products'},payload=>{const updated=payload.new,shop=shops.find(s=>s.id===updated.shop_id),product=shop?.products.find(p=>p.sku===updated.sku);if(product){product.quantity=Number(updated.quantity);product.stock=product.quantity===0?'Out of stock':product.quantity<=5?'Low stock':'In stock';if(state.shop?.id===shop.id)openShop(shop.id)}}).subscribe()}
inventoryChannel?.addEventListener('message',event=>{const {shopId,sku,quantity,stock,actorId}=event.data||{},identity=window.ZWOffline?.identity()||{};if(actorId!==identity.userId)return;const product=shops.find(s=>s.id===shopId)?.products.find(p=>p.sku===sku);if(product){product.quantity=quantity;product.stock=stock;if(state.portalTab==='sync')renderSyncCenter()}});
window.addEventListener('online',()=>{updateSyncStatus();if(inventorySync.auto)flushInventoryQueue()});window.addEventListener('offline',()=>{updateSyncStatus();showToast('You are offline — stock changes will be saved locally','cloud-off')});
let restoredOfflineIdentity='';window.addEventListener('zwconnect:identity-change',async event=>{const detail=event.detail||{},key=`${detail.userId||''}:${detail.shopId||''}:${detail.role||''}`;if(!detail.userId||!['worker','shop_owner'].includes(detail.role)||key===restoredOfflineIdentity)return;restoredOfflineIdentity=key;if(navigator.onLine)await hydrateProductsFromSupabase();state.localStateRestored=false;await restorePendingLocalState();await updateSyncStatus()});
const ACCOUNT_BOUND_FORMS=new Set(['saleForm','workerCartCheckout','inventoryMovementForm','stockPurchaseForm','purchaseExpenseForm','paymentMethodForm','workerForm','shopImageForm']);document.addEventListener('submit',event=>{if(!ACCOUNT_BOUND_FORMS.has(event.target.id))return;if(window.ZWOffline?.identity().userId)return;event.preventDefault();event.stopImmediatePropagation();showToast('Sign in to a verified worker or owner account before recording offline changes.','lock-keyhole')},true);document.addEventListener('click',event=>{if(!event.target.closest('[data-confirm-payment],[data-reject-payment],[data-cart-confirm],[data-cart-reject]'))return;if(window.ZWOffline?.identity().userId)return;event.preventDefault();event.stopImmediatePropagation();showToast('Sign in to the responsible worker or owner account first.','lock-keyhole')},true);
function showOnly(id){['homePage','shopsPage','shopPage','portalPage'].forEach(x=>$(`#${x}`).classList.toggle('hidden',x!==id));$('.site-header').classList.toggle('hidden',id==='portalPage');$('.site-footer').classList.toggle('hidden',id==='portalPage');document.body.classList.toggle('portal-active',id==='portalPage');document.body.dataset.view=id;window.scrollTo({top:0,behavior:'smooth'})}
function renderProfiles(filter=''){const cards=profiles.filter(p=>(p.title+p.desc).toLowerCase().includes(filter.toLowerCase())).map(p=>{const count=shops.filter(s=>s.profile===p.id).length;return `<button class="profile-card" data-profile="${p.id}"><span class="profile-icon" style="background:${p.color};color:${p.ink}"><i data-lucide="${p.icon}"></i></span><h3>${p.title}</h3><p>${p.desc}</p><footer><strong>${count} ${count===1?'shop':'shops'}</strong><span>Browse <i data-lucide="chevron-right"></i></span></footer></button>`}).join('');$('#profileGrid').innerHTML=cards||'<p>No matching profile found.</p>';icons()}
function locationSuccess(position){state.userLocation={lat:position.coords.latitude,lng:position.coords.longitude};state.city='Current location';$('#locationLabel').textContent='Current location';showToast('Location enabled — shops can now be sorted by distance','locate-fixed');if(state.profile)renderShops()}
function requestLocation(){if(!navigator.geolocation){showToast('Location is not supported by this browser','triangle-alert');return}$('#locationLabel').textContent='Locating…';navigator.geolocation.getCurrentPosition(locationSuccess,()=>{state.userLocation=cities.harare;state.city='Harare';$('#locationLabel').textContent='Harare';$('#citySelect').value='harare';showToast('Location permission unavailable — showing Harare','map-pin')},{enableHighAccuracy:true,timeout:8000,maximumAge:300000})}
function setCity(key){if(!key)return;state.userLocation=cities[key];state.city=cities[key].name;$('#locationLabel').textContent=state.city;showToast(`Showing shops near ${state.city}`,'map-pin');if(state.profile)renderShops()}
function openProfile(id){state.profile=id;const p=profileById(id);$('#shopsCrumb').textContent=p.title;$('#listingTitle').textContent=p.title;$('#listingDescription').textContent=p.desc;$('#listingIcon').style.background=p.color;$('#listingIcon').style.color=p.ink;$('#listingIcon').innerHTML=`<i data-lucide="${p.icon}"></i>`;$('#shopSearch').value='';showOnly('shopsPage');renderShops();history.replaceState(null,'',`#profile/${id}`)}
function renderShops(filter=''){let list=shops.filter(s=>s.profile===state.profile&&(s.name+s.city+s.address).toLowerCase().includes(filter.toLowerCase()));if(state.sortNearest&&state.userLocation)list.sort((a,b)=>shopDistance(a)-shopDistance(b));$('#shopCount').textContent=`${list.length} ${list.length===1?'approved shop':'approved shops'}`;$('#shopGrid').innerHTML=list.map(s=>{const d=shopDistance(s);return `<button class="shop-card" data-shop="${s.id}"><div class="shop-card-image"><img src="${s.image}" alt="${s.name} storefront"><span class="verified"><i data-lucide="badge-check"></i> Verified</span>${d!==null?`<span class="distance-badge">${d.toFixed(1)} km</span>`:''}</div><div class="shop-card-body"><h3>${s.name}</h3><span class="shop-address"><i data-lucide="map-pin"></i>${s.address}</span><div class="shop-meta"><span class="${s.open?'open':'closed'}">${s.open?'Open now':'Closed'}</span><span class="rating">★ ${s.rating}</span><span class="trade-mode ${s.salesMode}">${salesModeLabel(s.salesMode)}</span></div><div class="shop-stock"><span><strong>${s.products.filter(p=>p.stock!=='Out of stock').length}</strong> items available</span><span>View prices</span></div></div></button>`}).join('');$('#emptyShops').classList.toggle('hidden',list.length>0);$('#shopGrid').classList.toggle('hidden',list.length===0);renderMap(list);icons()}
function renderMap(list){if(!window.L)return;const center=state.userLocation||{lat:list[0]?.lat||-17.8252,lng:list[0]?.lng||31.0335};if(!state.map){state.map=L.map('shopMap',{zoomControl:true}).setView([center.lat,center.lng],11);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; OpenStreetMap contributors'}).addTo(state.map)}state.markers.forEach(m=>m.remove());state.markers=[];list.forEach(s=>{const m=L.marker([s.lat,s.lng]).addTo(state.map).bindPopup(`<strong>${s.name}</strong><br>${s.address}`);state.markers.push(m)});if(state.userLocation){const m=L.circleMarker([state.userLocation.lat,state.userLocation.lng],{radius:7,color:'#08755c',fillColor:'#31c899',fillOpacity:1}).addTo(state.map).bindPopup('Your location');state.markers.push(m)}state.map.setView([center.lat,center.lng],state.userLocation?12:10);setTimeout(()=>state.map.invalidateSize(),120)}
const PRODUCT_SHARE_ORIGIN='https://zwconnect.co.zw/';
function productShareUrl(shopId,sku){const url=new URL(PRODUCT_SHARE_ORIGIN);url.searchParams.set('shop',shopId);url.searchParams.set('product',sku);return url.toString()}
async function shareProduct(shopId,sku){const shop=shops.find(s=>s.id===shopId),product=shop?.products.find(p=>p.sku===sku);if(!shop||!product)return;const url=productShareUrl(shopId,sku),data={title:`${product.name} at ${shop.name}`,text:`${product.name} — US$ ${product.price.toFixed(2)} • ${product.stock} at ${shop.name}`,url};try{if(navigator.share){await navigator.share(data);return}await navigator.clipboard.writeText(`${data.text}\n${url}`);showToast('Product link copied — ready to share','share-2')}catch(err){if(err?.name!=='AbortError')showToast('Could not share this product','triangle-alert')}}
function openShop(id,productSku=''){const shop=shops.find(s=>s.id===id);if(!shop)return;const p=profileById(shop.profile),d=shopDistance(shop);state.shop=shop;$('#shopProfileCrumb').textContent=p.title;$('#shopNameCrumb').textContent=shop.name;$('#shopDetail').innerHTML=`<section class="shop-hero"><img src="${shop.image}" alt="${shop.name}"><div class="shop-hero-content"><span class="verified"><i data-lucide="badge-check"></i> Approved ZWConnect shop</span><h1>${shop.name}</h1><p>${p.title} • ${salesModeLabel(shop.salesMode)} • ${shop.address}</p></div></section><section class="shop-info-grid"><div><i data-lucide="clock-3"></i><span><strong class="${shop.open?'open':'closed'}">${shop.open?'Open today':'Currently closed'}</strong><small>08:00–18:00</small></span></div><div><i data-lucide="navigation"></i><span><strong>${d!==null?`${d.toFixed(1)} km away`:'Set location for distance'}</strong><small>${shop.city}, Zimbabwe</small></span></div><div><i data-lucide="star"></i><span><strong>${shop.rating} customer rating</strong><small>Verified business listing</small></span></div></section><section><div class="catalog-head"><div><p class="kicker">PUBLIC CATALOGUE</p><h2>Prices and availability</h2><p>${salesModeLabel(shop.salesMode)} pricing, updated by ${shop.name}. Pay with verified shop details; stock moves only after confirmation.</p></div><button class="secondary-button"><i data-lucide="phone"></i> Contact shop</button></div><div class="product-grid">${shop.products.map(x=>`<article class="product-card ${x.sku===productSku?'shared-product':''}" data-product-sku="${x.sku}"><div class="product-visual">${x.emoji}</div><h3>${x.name}</h3><span class="sku">${x.sku}</span>${productPriceMarkup(shop,x)}<div class="price-row"><small>${x.quantity} units • ${Math.floor(x.quantity/x.caseSize)} full cases</small><span class="stock-state ${x.stock==='Low stock'?'low':x.stock==='Out of stock'?'out':''}">${x.stock}</span></div><div class="product-actions"><button class="product-pay" data-pay-product="${x.sku}" data-pay-shop="${shop.id}" ${x.quantity<1?'disabled':''}><i data-lucide="wallet-cards"></i> Pay shop</button><button class="product-share" data-share-product="${x.sku}" data-share-shop="${shop.id}" aria-label="Share ${x.name}"><i data-lucide="share-2"></i> Share</button></div></article>`).join('')}</div></section>`;showOnly('shopPage');history.replaceState(null,'',productSku?`?shop=${encodeURIComponent(id)}&product=${encodeURIComponent(productSku)}`:`#shop/${id}`);icons();if(productSku)setTimeout(()=>document.querySelector(`[data-product-sku="${CSS.escape(productSku)}"]`)?.scrollIntoView({behavior:'smooth',block:'center'}),100)}
function routeHome(){state.profile=null;state.shop=null;showOnly('homePage');history.replaceState(null,'','#profiles');setTimeout(()=>$('#profiles').scrollIntoView({behavior:'smooth'}),50)}
async function signOutBusinessPortal(){try{await window.zwconnectSupabase?.auth.signOut({scope:'local'})}catch{}await window.ZWOffline?.setContext('public',{userId:null,email:null,shopId:null,force:true});state.portalRole=null;state.portalTab=null;routeHome();showToast('Signed out. This account’s offline changes remain safely locked on this device.','lock-keyhole')}
function openModal(id){$(`#${id}`).classList.add('open');$(`#${id}`).setAttribute('aria-hidden','false');document.body.style.overflow='hidden'}
function closeModal(id){$(`#${id}`).classList.remove('open');$(`#${id}`).setAttribute('aria-hidden','true');document.body.style.overflow=''}
function populateRegistration(){if(!$('#registrationProfile').options.length)$('#registrationProfile').innerHTML=profiles.map(p=>`<option value="${p.id}">${p.title}</option>`).join('')}
const commandActions=[
 {id:'browse',label:'Browse all shop profiles',detail:'Explore every business category',icon:'layout-grid',keywords:'home categories profiles'},
 {id:'nearby',label:'Find shops near me',detail:'Use free browser location',icon:'navigation',keywords:'location map distance'},
 {id:'register',label:'List my shop',detail:'Apply for owner approval',icon:'store',keywords:'register business owner'},
 {id:'login',label:'Open portal login',detail:'Owner and worker access',icon:'log-in',keywords:'account staff worker owner'},
 {id:'install',label:'Install ZWConnect',detail:'Add the app to this device',icon:'download',keywords:'pwa shortcut app'}
];
function commandItems(query=''){const q=query.trim().toLowerCase(),matches=text=>!q||text.toLowerCase().includes(q);const actions=commandActions.filter(x=>matches(`${x.label} ${x.detail} ${x.keywords}`)).map(x=>({...x,kind:'action',group:'Quick actions'}));const profileItems=profiles.filter(x=>matches(`${x.title} ${x.desc} ${x.tools.join(' ')}`)).map(x=>({id:x.id,label:x.title,detail:`${shops.filter(s=>s.profile===x.id).length} available shops`,icon:x.icon,kind:'profile',group:'Shop profiles'}));const shopItems=shops.filter(x=>matches(`${x.name} ${x.city} ${x.address}`)).map(x=>({id:x.id,label:x.name,detail:`${profileById(x.profile).title} • ${x.city}`,icon:'store',kind:'shop',group:'Shops'}));const productItems=shops.flatMap(shop=>shop.products.filter(x=>x.quantity>0&&matches(`${x.name} ${x.sku} ${shop.name}`)).map(x=>({id:`${shop.id}|${x.sku}`,label:x.name,detail:`US$ ${x.price.toFixed(2)} • ${x.stock} • ${shop.name}`,icon:'package-search',kind:'product',group:'Products'})));return [...actions,...profileItems,...shopItems,...productItems].slice(0,10)}
function renderCommandResults(query=''){const items=commandItems(query),container=$('#commandResults');container.innerHTML=items.length?items.map((item,index)=>`<button class="command-result ${index===0?'selected':''}" data-command-kind="${item.kind}" data-command-id="${item.id}"><span><i data-lucide="${item.icon}"></i></span><div><strong>${item.label}</strong><small>${item.detail}</small></div><em>${item.group}</em><i data-lucide="arrow-up-right"></i></button>`).join(''):`<div class="command-empty"><i data-lucide="search-x"></i><strong>No result found</strong><small>Try a category, shop name, product or action.</small></div>`;icons()}
function openCommandPalette(query=''){openModal('commandPalette');$('#commandInput').value=query;renderCommandResults(query);setTimeout(()=>$('#commandInput').focus(),40)}
function runCommand(kind,id){closeModal('commandPalette');$('#globalSearch').value='';if(kind==='profile')openProfile(id);else if(kind==='shop')openShop(id);else if(kind==='product'){const [shopId,sku]=id.split('|');openShop(shopId,sku)}else if(id==='browse')routeHome();else if(id==='nearby')requestLocation();else if(id==='register'){populateRegistration();openModal('registrationModal')}else if(id==='login')openModal('loginModal');else if(id==='install')installApp()}

const portalConfigs={
 admin:{label:'Site administration',name:'Simba Dube',initials:'SD',role:'Site admin',nav:[['overview','layout-dashboard','Overview'],['approvals','badge-check','Owner approvals'],['businesses','store','Businesses'],['users','users','Accounts'],['audit','scroll-text','Audit log']]},
 owner:{label:'Shop owner portal',name:'Tariro Moyo',initials:'TM',role:'Shop owner',nav:[['overview','layout-dashboard','Overview'],['sell','scan-barcode','Sell'],['purchasing','package-plus','Purchasing & expenses'],['profit','chart-no-axes-combined','Profit analysis'],['ledger','book-open-check','Sales ledger'],['setup','store','Shop setup'],['catalog','package-open','Products'],['payments','wallet-cards','Payment details'],['confirmations','badge-check','Confirm payments'],['workers','users','Workers'],['sync','refresh-cw','Inventory sync'],['subscription','badge-dollar-sign','Subscription'],['reports','chart-no-axes-combined','Reports']]},
 worker:{label:'Worker portal',name:'Chipo M.',initials:'CM',role:'Cashier • Mbare Market',nav:[['sell','scan-barcode','Sell'],['purchasing','package-plus','Purchasing'],['orders','package-check','Dispatch orders'],['sales','receipt-text','My sales'],['sync','refresh-cw','Inventory sync'],['customers','users','Customers'],['shift','clock-3','My shift']]}
};
function openPortal(role,tab){if(role==='admin'){window.location.href='./admin/?demo=1';return}closeModal('loginModal');window.ZWOffline?.setContext(role==='owner'?'shop_owner':'worker');const c=portalConfigs[role];state.portalRole=role;state.portalTab=tab||c.nav[0][0];$('#portalRoleLabel').textContent=c.label;$('#portalUserName').textContent=c.name;$('#portalInitials').textContent=c.initials;$('#portalUserRole').textContent=c.role;$('#portalNav').innerHTML=c.nav.map(n=>`<button class="portal-nav-button ${state.portalTab===n[0]?'active':''}" data-portal-tab="${n[0]}"><i data-lucide="${n[1]}"></i><span>${n[2]}</span></button>`).join('');showOnly('portalPage');renderPortal();icons()}
async function authenticateBusinessPortal(form){const db=window.zwconnectSupabase;if(!db)return showToast('Supabase must be connected before business accounts can sign in.','cloud-off');const values=Object.fromEntries(new FormData(form)),email=String(values.email||'').trim().toLowerCase();const submit=form.querySelector('[type="submit"]');submit.disabled=true;submit.textContent='Signing in…';try{const {data:authData,error:authError}=await db.auth.signInWithPassword({email,password:values.password});if(authError)throw authError;const user=authData.user,{data:roleRow,error:roleError}=await db.from('account_roles').select('role').eq('user_id',user.id).single();if(roleError||!roleRow)throw roleError||new Error('No approved business role is assigned to this account');const role=roleRow.role;let shopId=null;if(role==='shop_owner'){const {data}=await db.from('shops').select('id').eq('owner_id',user.id).is('deleted_at',null).limit(1).maybeSingle();shopId=data?.id||null}else if(role==='worker'){const {data}=await db.from('shop_workers').select('shop_id').eq('user_id',user.id).eq('active',true).limit(1).maybeSingle();shopId=data?.shop_id||null}await window.ZWOffline.setContext(role,{userId:user.id,email:user.email||email,shopId,force:true});if(role==='site_admin'){sessionStorage.setItem('zwconnect_admin_email',email);location.href='./admin/';return}if(role==='courier'){location.href='./courier/';return}if(role==='shop_owner')openPortal('owner',requestedWorkspace==='owner'?requestedWorkspaceTab:null);else if(role==='worker')openPortal('worker',requestedWorkspace==='worker'?requestedWorkspaceTab:null);else throw new Error('This role does not have a business portal')}catch(error){try{await db.auth.signOut({scope:'local'})}catch{}await window.ZWOffline?.setContext('public',{userId:null,email:null,shopId:null,force:true});showToast(error.message||'Business sign-in failed','shield-x')}finally{submit.disabled=false;submit.textContent='Sign in securely'}}
function renderPortal(){const role=state.portalRole,tab=state.portalTab,c=portalConfigs[role],nav=c.nav.find(n=>n[0]===tab)||c.nav[0];$('#portalTitle').textContent=nav[2];$('#portalKicker').textContent=c.label.toUpperCase();$$('.portal-nav-button').forEach(b=>b.classList.toggle('active',b.dataset.portalTab===tab));if(role==='admin')renderAdmin(tab);if(role==='owner')renderOwner(tab);if(role==='worker')renderWorker(tab);updateSyncStatus();icons()}
function metric(icon,label,value){return `<article class="portal-metric"><span><i data-lucide="${icon}"></i></span><div><small>${label}</small><strong>${value}</strong></div></article>`}
function renderAdmin(tab){const pending=ownerApplications.filter(a=>a.status==='pending');if(tab!=='approvals'&&tab!=='overview'){$('#portalContent').innerHTML=`<section class="portal-panel"><div class="panel-head"><div><h2>${portalConfigs.admin.nav.find(x=>x[0]===tab)[2]}</h2><p>Role-restricted administrative workspace.</p></div></div><div class="empty-state"><i data-lucide="shield-check"></i><h3>Protected admin module</h3><p>This module is available only to the site_admin role.</p></div></section>`;return}$('#portalContent').innerHTML=`${tab==='overview'?`<div class="metric-grid">${metric('store','Approved shops',shops.length)}${metric('clipboard-clock','Pending applications',pending.length)}${metric('users','Active owners','14')}${metric('map-pinned','Cities covered','6')}</div>`:''}<section class="portal-panel"><div class="panel-head"><div><h2>Owner registration approvals</h2><p>Verify ownership and shop proof before granting access.</p></div><span class="status-pill">${pending.length} pending</span></div><div class="portal-table-wrap"><table class="portal-table"><thead><tr><th>Owner</th><th>Business</th><th>Profile</th><th>City</th><th>Proof</th><th>Applied</th><th>Decision</th></tr></thead><tbody>${pending.length?pending.map(a=>`<tr><td><strong>${a.owner}</strong></td><td>${a.business}</td><td>${profileById(a.profile)?.title||a.profile}</td><td>${a.city}</td><td>${a.proof?`<a class="proof-link" href="${a.proof.url}" target="_blank" rel="noopener">View proof</a>`:'Missing'}</td><td>${a.date}</td><td><button data-approve="${a.id}">Approve</button><button class="reject" data-reject="${a.id}">Reject</button></td></tr>`).join(''):`<tr><td colspan="7">No applications waiting for review.</td></tr>`}</tbody></table></div></section><div class="permission-note"><strong>Separation of duties:</strong> site admins approve owners and moderate the network, but cannot operate a shop register, change shop stock or create worker sales.</div>`}
function renderOwnerSubscription(){$('#portalContent').innerHTML=`<div class="metric-grid">${metric('badge-check','Subscription','Active')}${metric('circle-dollar-sign','Plan amount','US$ 25.00')}${metric('calendar-days','Billing duration','30 days')}${metric('clock-3','Renews','18 Dec 2026')}</div><section class="portal-panel subscription-owner"><div class="panel-head"><div><h2>Platform subscription</h2><p>Visible only to this shop owner and the site administrator.</p></div><span class="status-pill approved">Active</span></div><div class="subscription-summary"><div><small>SHOP</small><strong>Mbare Market Fresh</strong></div><div><small>CURRENT PERIOD</small><strong>19 Nov–18 Dec 2026</strong></div><div><small>ACCESS</small><strong>POS, catalogue, workers and reports</strong></div></div><div class="permission-note"><strong>Managed by ZWConnect:</strong> contact the site administrator to change the amount, duration or request a trial period. Workers cannot view subscription or billing details.</div></section>`}
function renderOwnerOverview(){const products=shops[0].products,low=products.filter(p=>p.quantity<=5);$('#portalContent').innerHTML=`<div class="metric-grid">${metric('circle-dollar-sign','Sales today','US$ 4,286')}${metric('shopping-basket','Transactions','148')}${metric('package-check','Products online','326')}${metric('users','Workers',`${workers.length}/7`)}</div><section class="quick-actions"><div><p class="kicker">QUICK ACTIONS</p><h2>Keep the shop moving</h2></div><button data-quick-tab="catalog"><span><i data-lucide="package-plus"></i></span><strong>Add product</strong><small>Grow the catalogue</small></button><button data-quick-tab="sync"><span><i data-lucide="package-check"></i></span><strong>Move stock</strong><small>Works offline</small></button><button data-quick-tab="workers"><span><i data-lucide="user-plus"></i></span><strong>Invite worker</strong><small>${7-workers.length} seats left</small></button><button data-quick-action="storefront"><span><i data-lucide="external-link"></i></span><strong>View storefront</strong><small>See what customers see</small></button></section><div class="owner-dashboard-grid"><section class="portal-panel low-stock-panel"><div class="panel-head"><div><h2>Stock attention</h2><p>Products at or below the low-stock threshold.</p></div><span class="alert-count">${low.length} need attention</span></div><div class="attention-list">${low.length?low.map(p=>`<button data-quick-tab="sync"><span class="product-dot">${p.emoji}</span><div><strong>${p.name}</strong><small>${p.sku} • ${p.stock}</small></div><b>${p.quantity}</b><i data-lucide="chevron-right"></i></button>`).join(''):'<div class="all-clear"><i data-lucide="circle-check"></i><strong>Stock levels look healthy</strong></div>'}</div></section><section class="portal-panel shop-health"><div class="panel-head"><div><h2>Shop health</h2><p>Small improvements that build customer trust.</p></div><strong class="health-score">85%</strong></div><div class="health-progress"><span></span></div><div class="health-list"><span><i data-lucide="badge-check"></i> Business approved</span><span><i data-lucide="map-pin-check"></i> Location active</span><span><i data-lucide="package-check"></i> Catalogue live</span><span class="pending"><i data-lucide="camera"></i> Add more shop photos</span></div><button class="secondary-button" data-quick-tab="setup">Improve shop profile</button></section></div>`}
function ledgerRowsMarkup(rows){return rows.map(row=>`<tr><td><strong>${escapeHtml(row.entry_type==='pos_sale'?'POS sale':String(row.entry_type).replaceAll('_',' '))}</strong><small>${new Date(row.posted_at).toLocaleString()}</small></td><td><span class="status-pill approved">${escapeHtml(row.completed_by_role||'shop team')}</span><strong>${escapeHtml(row.completed_by_name||'Recorded user')}</strong></td><td>${escapeHtml(row.debit_account)} → ${escapeHtml(row.credit_account)}</td><td>${escapeHtml(row.memo||'Sale posting')}</td><td><strong>US$ ${Number(row.amount||0).toFixed(2)}</strong></td></tr>`).join('')}
async function renderOwnerLedger(){const demo=[{entry_type:'pos_sale',posted_at:new Date().toISOString(),completed_by_role:'shop_owner',completed_by_name:portalConfigs.owner.name,debit_account:'cash',credit_account:'sales_revenue',memo:'Owner-completed register sale',amount:42.50},{entry_type:'customer_payment',posted_at:new Date(Date.now()-3600000).toISOString(),completed_by_role:'worker',completed_by_name:'Chipo M.',debit_account:'payment_clearing',credit_account:'sales_revenue',memo:'Online order payment confirmed',amount:18.75}];const render=rows=>{$('#portalContent').innerHTML=`<div class="metric-grid">${metric('book-open-check','Ledger entries',rows.length)}${metric('user-check','Completed by','Always recorded')}${metric('shield-check','Posting identity','Authenticated user')}${metric('cloud-check','Offline sales','Stamped on sync')}</div><section class="portal-panel"><div class="panel-head"><div><h2>Sales ledger</h2><p>Every sale shows the owner or worker who completed and posted it.</p></div><span class="status-pill approved">Owner only</span></div><div class="portal-table-wrap"><table class="portal-table"><thead><tr><th>Entry</th><th>Completed by</th><th>Accounts</th><th>Memo</th><th>Amount</th></tr></thead><tbody>${ledgerRowsMarkup(rows)}</tbody></table></div></section>`;icons()};render(demo);const shopId=databaseShopId(shops[0]);if(!window.zwconnectSupabase||!navigator.onLine||!shopId)return;const {data,error}=await window.zwconnectSupabase.from('ledger_entries').select('id,entry_type,debit_account,credit_account,amount,memo,completed_by_name,completed_by_role,posted_at').eq('shop_id',shopId).order('posted_at',{ascending:false}).limit(50);if(!error&&data?.length&&state.portalRole==='owner'&&state.portalTab==='ledger')render(data)}
function renderOwner(tab){if(tab==='overview'){renderOwnerOverview();return}if(tab==='sell'){renderRegister();return}if(tab==='ledger'){renderOwnerLedger();return}if(tab==='payments'){renderPaymentSettings();return}if(tab==='confirmations'){renderPaymentConfirmations();return}if(tab==='workers'){renderWorkers();return}if(tab==='sync'){renderSyncCenter();return}if(tab==='subscription'){renderOwnerSubscription();return}if(tab!=='setup'){$('#portalContent').innerHTML=`<section class="portal-panel"><div class="panel-head"><div><h2>${portalConfigs.owner.nav.find(x=>x[0]===tab)[2]}</h2><p>Data is isolated to Mbare Market and its approved branches.</p></div></div><div class="empty-state"><i data-lucide="store"></i><h3>Owner-only shop module</h3><p>Workers see only the modules granted by their job assignment.</p></div></section>`;return}$('#portalContent').innerHTML=`<div class="metric-grid">${metric('circle-dollar-sign','Sales today','US$ 4,286')}${metric('shopping-basket','Transactions','148')}${metric('package-check','Products online','326')}${metric('users','Workers',`${workers.length}/7`)}</div><div class="owner-layout"><section class="portal-panel"><div class="panel-head"><div><h2>Shop setup</h2><p>Complete these items before publishing your storefront.</p></div><span class="status-pill approved">Published</span></div><div class="setup-list"><div class="setup-item"><span>1</span><div><strong>Business identity</strong><small>Mbare Market Fresh • approved</small></div><i data-lucide="circle-check"></i></div><div class="setup-item"><span>2</span><div><strong>Trading model</strong><small>Wholesale & retail • unit and case pricing</small></div><i data-lucide="circle-check"></i></div><div class="setup-item"><span>3</span><div><strong>Payment details</strong><small>${paymentMethodsFor(shops[0]).length} customer payment methods enabled</small></div><i data-lucide="circle-check"></i></div><div class="setup-item"><span>4</span><div><strong>Free map location</strong><small>-17.8585, 31.0451 • OpenStreetMap</small></div><i data-lucide="circle-check"></i></div><div class="setup-item"><span>5</span><div><strong>Public catalogue</strong><small>326 products with price and stock</small></div><i data-lucide="circle-check"></i></div><div class="setup-item"><span>6</span><div><strong>Trading hours</strong><small>Mon–Sat, 08:00–18:00</small></div><i data-lucide="circle-check"></i></div></div></section><section class="portal-panel"><div class="panel-head"><div><h2>Location</h2><p>Free browser positioning</p></div></div><div class="empty-state"><i data-lucide="map-pinned"></i><h3>Shop pin is active</h3><p>Customers and couriers can calculate distance.</p><button class="secondary-button" id="ownerLocate"><i data-lucide="locate-fixed"></i> Update location</button></div></section></div>`}
function renderWorkers(){const maxed=workers.length>=7;$('#portalContent').innerHTML=`<section class="portal-panel"><div class="panel-head"><div><h2>Worker accounts</h2><p>Each worker belongs to this shop and receives one job assignment.</p></div><span class="staff-count">${workers.length} of 7 accounts</span></div><form class="worker-form" id="workerForm"><input name="name" required placeholder="Worker name"><input name="email" type="email" required placeholder="Email address"><select name="job"><option>Cashier</option><option>Stock controller</option><option>Branch manager</option><option>Procurement</option><option>Accountant</option></select><button class="primary-button" ${maxed?'disabled':''}>${maxed?'Limit reached':'Create account'}</button></form><div class="permission-note"><strong>Secure account flow:</strong> the owner sends an invitation. The worker chooses their password. Owners never see worker passwords, and workers cannot access another shop.</div><div class="portal-table-wrap"><table class="portal-table"><thead><tr><th>Worker</th><th>Email</th><th>Job assignment</th><th>Status</th><th>Action</th></tr></thead><tbody>${workers.map((w,i)=>`<tr><td><strong>${w.name}</strong></td><td>${w.email}</td><td>${w.job}</td><td><span class="status-pill ${w.status==='Active'?'approved':''}">${w.status}</span></td><td><button class="reject" data-remove-worker="${i}">Deactivate</button></td></tr>`).join('')}</tbody></table></div><div class="worker-limit"><span>Worker capacity</span><div class="progress"><span style="width:${workers.length/7*100}%"></span></div><strong>${workers.length}/7</strong></div></section>`}
function renderRegister(){const shop=shops[0],products=shop.products;$('#portalContent').innerHTML=`<div class="metric-grid">${metric('circle-dollar-sign','My sales today','US$ 842')}${metric('receipt-text','Transactions','31')}${metric('clock-3','Shift started','08:02')}${metric('wallet-cards','Drawer expected','US$ 318')}</div><section class="portal-panel offline-register"><div class="panel-head"><div><h2>Offline-ready register</h2><p>${salesModeLabel(shop.salesMode)} register. Every receipt gets a unique sync ID.</p></div><span class="status-pill ${navigator.onLine?'approved':''}">${navigator.onLine?'Online':'Offline mode'}</span></div><form id="saleForm" class="sale-form"><label>Product<select name="sku" id="saleProduct">${products.map(p=>`<option value="${p.sku}">${p.name} • ${p.quantity} units</option>`).join('')}</select></label><label>Sell as<select name="saleUnit" id="saleUnit">${saleUnitOptions(shop)}</select></label><label>Quantity<input name="quantity" type="number" min="1" step="1" value="1" required><small id="saleQuantityHint">Number of units</small></label><label>Payment<select name="payment"><option value="cash">Cash</option><option value="ecocash">EcoCash</option><option value="card">Card</option><option value="bank_transfer">Bank transfer</option></select></label><div class="sale-total"><small id="salePackageLabel">1 singular unit</small><strong id="saleTotal">US$ ${products[0]?.price.toFixed(2)||'0.00'}</strong></div><button class="primary-button" type="submit"><i data-lucide="receipt-text"></i> Complete sale</button></form><div class="register-products">${products.map(p=>`<div><span>${p.emoji}</span><div><strong>${p.name}</strong><small>${p.quantity} units • ${Math.floor(p.quantity/p.caseSize)} full cases</small><em>Unit US$ ${p.price.toFixed(2)} • Case of ${p.caseSize} US$ ${p.casePrice.toFixed(2)}</em></div><b>${p.quantity}</b></div>`).join('')}</div></section><div class="permission-note"><strong>Case stock rule:</strong> inventory is stored in base units. Selling 2 cases of 6 deducts 12 units, while selling 2 singular units deducts only 2. Pending sales are replayed after a restart.</div>`;updateSalePreview();icons()}
function renderWorker(tab){if(tab==='sync'){renderSyncCenter();return}if(tab==='sell'){renderRegister();return}if(tab==='orders'){renderPaymentConfirmations();return}$('#portalContent').innerHTML=`<div class="metric-grid">${metric('circle-dollar-sign','My sales today','US$ 842')}${metric('receipt-text','Transactions','31')}${metric('clock-3','Shift started','08:02')}${metric('wallet-cards','Drawer expected','US$ 318')}</div><section class="portal-panel"><div class="panel-head"><div><h2>${portalConfigs.worker.nav.find(x=>x[0]===tab)?.[2]}</h2><p>Worker access is restricted to Mbare Market and the assigned Cashier job.</p></div><span class="status-pill approved">Shift open</span></div><div class="empty-state"><i data-lucide="scan-barcode"></i><h3>Cashier workspace</h3><p>Only cashier-authorised records are visible here.</p></div></section><div class="permission-note"><strong>Worker boundary:</strong> no access to owner settings, other shops, owner approvals, billing, staff creation or restricted stock-cost reports.</div>`}
function renderSyncCenter(){const products=shops[0].products,history=inventorySync.history.slice(0,8);$('#portalContent').innerHTML=`<div class="sync-hero ${navigator.onLine?'online':'offline'}"><span><i data-lucide="${navigator.onLine?'cloud-check':'cloud-off'}"></i></span><div><p class="kicker">OFFLINE-FIRST INVENTORY</p><h2>${navigator.onLine?'Connected and ready to sync':'Working safely offline'}</h2><p>${navigator.onLine?'Changes sync automatically and live product updates arrive in real time.':'Every movement is saved on this device and will upload when the connection returns.'}</p></div><label class="auto-sync-toggle"><input id="autoSyncToggle" type="checkbox" ${inventorySync.auto?'checked':''}><span></span><strong>Auto sync</strong></label></div><div class="sync-layout"><section class="portal-panel"><div class="panel-head"><div><h2>Record product movement</h2><p>Updates stock locally first, even without a network.</p></div><span class="status-pill ${navigator.onLine?'approved':''}">${navigator.onLine?'Online':'Offline'}</span></div><form class="movement-form" id="inventoryMovementForm"><label>Product<select name="sku">${products.map(p=>`<option value="${p.sku}">${p.name} • ${p.quantity} available</option>`).join('')}</select></label><label>Quantity change<input name="delta" type="number" step="1" placeholder="e.g. -2 or 12" required></label><label>Reason<select name="reason"><option value="sale">Sale</option><option value="restock">Restock</option><option value="return">Customer return</option><option value="damage">Damage / loss</option><option value="count">Stock count correction</option></select></label><button class="primary-button" type="submit"><i data-lucide="package-check"></i> Save movement</button></form><div class="stock-snapshot">${products.map(p=>`<div><span>${p.emoji}</span><strong>${p.name}</strong><small>${p.sku}</small><b class="${p.quantity<=5?'low':''}">${p.quantity}</b></div>`).join('')}</div></section><section class="portal-panel"><div class="panel-head"><div><h2>Sync queue</h2><p>Idempotent changes waiting for the cloud.</p></div><button class="secondary-button" id="syncNowButton" ${!navigator.onLine?'disabled':''}><i data-lucide="refresh-cw"></i> Sync now</button></div><div class="movement-history">${history.length?history.map(m=>`<div><span class="movement-icon ${m.delta>0?'in':'out'}"><i data-lucide="${m.delta>0?'package-plus':'package-minus'}"></i></span><div><strong>${m.product}</strong><small>${m.reason} • ${new Date(m.occurredAt).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</small></div><b>${m.delta>0?'+':''}${m.delta}</b><em class="${m.status}">${m.status}</em></div>`).join(''):'<div class="sync-empty"><i data-lucide="cloud-check"></i><p>No pending movements. This device is up to date.</p></div>'}</div></section></div>`;updateSyncStatus();icons()}
const renderInventorySyncCenter=renderSyncCenter;
async function renderOfflineActionQueuePanel(){const host=$('#portalContent .sync-layout');if(!host)return;const status=await window.ZWOffline.status(),labels={'sale.create':'Sale receipt','worker.invite':'Worker invitation','owner_application.submit':'Owner application','application.review':'Application decision','shop.update':'Shop update','shop.delete':'Shop deletion','subscription.update':'Subscription update','customer_order.submit':'Customer payment','customer_order.review':'Payment confirmation','payment_method.save':'Payment method','courier_application.submit':'Courier application','courier_application.review':'Courier decision','courier_rate.save':'Courier rates','courier_subscription.update':'Courier subscription'};host.insertAdjacentHTML('afterend',`<section class="portal-panel action-queue-panel"><div class="panel-head"><div><h2>All offline actions</h2><p>Saved locally until Supabase confirms each transaction.</p></div><span class="status-pill ${status.pending?'':'approved'}">${status.pending} pending</span></div><div class="movement-history">${status.items.length?status.items.map(item=>`<div><span class="movement-icon ${item.status==='failed'||item.status==='blocked'?'out':'in'}"><i data-lucide="${item.status==='failed'||item.status==='blocked'?'cloud-alert':'cloud-upload'}"></i></span><div><strong>${labels[item.type]||item.type}</strong><small>${new Date(item.createdAt).toLocaleString()}${item.lastError?` • ${item.lastError}`:''}</small></div><b>${item.attempts||0} tries</b><button class="queue-retry" data-retry-action="${item.id}">${item.status==='syncing'?'Syncing':item.status==='failed'||item.status==='blocked'?'Retry':'Queued'}</button></div>`).join(''):'<div class="sync-empty"><i data-lucide="cloud-check"></i><p>No queued sales or management actions for this role.</p></div>'}</div></section>`);icons()}
renderSyncCenter=function(){renderInventorySyncCenter();renderOfflineActionQueuePanel()};
async function submitRegistration(form){const data=new FormData(form),file=data.get('proof');if(!(file instanceof File)||!file.size){showToast('Upload a photo or PDF as proof of the shop','file-warning');return}if(file.size>10*1024*1024){showToast('Shop proof must be 10 MB or smaller','file-warning');return}const allowed=['image/jpeg','image/png','image/webp','application/pdf'];if(!allowed.includes(file.type)){showToast('Use a JPG, PNG, WebP or PDF proof file','file-warning');return}const id=Date.now(),profileId=data.get('profile'),application={id,owner:data.get('owner'),business:data.get('business'),profile:profileById(profileId)?.title||profileId,city:data.get('city'),salesMode:data.get('salesMode'),date:'20 Nov 2026',status:'pending',proof:{name:file.name,type:file.type,size:file.size}};try{await saveApplicationForAdmin(application,file)}catch{}ownerApplications.unshift({...application,proof:{...application.proof,url:URL.createObjectURL(file)}});await window.ZWOffline.enqueue('owner_application.submit',{owner:data.get('owner'),email:data.get('email'),phone:data.get('phone'),business:data.get('business'),profile:profileId,city:data.get('city'),address:data.get('address'),salesMode:data.get('salesMode'),proof:file},{role:'applicant'});closeModal('registrationModal');form.reset();$('#shopProofName').textContent='Choose a photo or PDF';showToast(navigator.onLine?'Application saved and queued for Supabase confirmation':'Application saved offline and will submit when connected','clipboard-check')}
async function installApp(){if(window.matchMedia('(display-mode: standalone)').matches||window.navigator.standalone){showToast('ZWConnect is already installed','badge-check');return}if(deferredInstallPrompt){deferredInstallPrompt.prompt();const choice=await deferredInstallPrompt.userChoice;deferredInstallPrompt=null;if(choice.outcome==='accepted')showToast('ZWConnect was added to your device','download');return}showToast(/iphone|ipad|ipod/i.test(navigator.userAgent)?'Tap Share, then Add to Home Screen':'Open your browser menu and choose Install app','smartphone')}

document.addEventListener('DOMContentLoaded',async()=>{
 await hydrateProductsFromSupabase();await restorePendingLocalState();renderProfiles();populateRegistration();icons();
 if('serviceWorker' in navigator)navigator.serviceWorker.register('./service-worker.js').catch(()=>{});
 setupRealtimeProducts();updateSyncStatus();if(navigator.onLine&&inventorySync.auto)flushInventoryQueue();
 window.ZWOffline?.subscribe(()=>updateSyncStatus());if(navigator.onLine&&inventorySync.auto)window.ZWOffline?.flush();
 $('#installAppButton').addEventListener('click',installApp);
 $('#syncStatusButton').addEventListener('click',()=>{if(['owner','worker'].includes(state.portalRole)){state.portalTab='sync';renderPortal()}});
 $('#shopProofInput').addEventListener('change',e=>{$('#shopProofName').textContent=e.target.files[0]?.name||'Choose a photo or PDF'});
 $('#profileSearch').addEventListener('input',e=>renderProfiles(e.target.value));
 $('#shopSearch').addEventListener('input',e=>renderShops(e.target.value));
 $('#useLocation').addEventListener('click',requestLocation);$('#headerLocation').addEventListener('click',requestLocation);$('#citySelect').addEventListener('change',e=>setCity(e.target.value));$('#portalSignOut').addEventListener('click',signOutBusinessPortal);
 $('#sortDistance').addEventListener('click',()=>{state.sortNearest=!state.sortNearest;$('#sortDistance').innerHTML=`<i data-lucide="arrow-down-up"></i> ${state.sortNearest?'Nearest first':'Default order'}`;renderShops()});
 $('#backToProfile').addEventListener('click',()=>openProfile(state.profile));
 $('#globalSearch').addEventListener('focus',e=>{e.target.blur();openCommandPalette(e.target.value)});
 $('#commandInput').addEventListener('input',e=>renderCommandResults(e.target.value));
 $('#commandInput').addEventListener('keydown',e=>{const results=$$('.command-result');let selected=results.findIndex(x=>x.classList.contains('selected'));if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();results[selected]?.classList.remove('selected');selected=e.key==='ArrowDown'?(selected+1)%results.length:(selected-1+results.length)%results.length;results[selected]?.classList.add('selected');results[selected]?.scrollIntoView({block:'nearest'})}if(e.key==='Enter'){e.preventDefault();results[Math.max(0,selected)]?.click()}});
 $('#loginForm').addEventListener('submit',e=>{e.preventDefault();authenticateBusinessPortal(e.currentTarget)});
 $('#registrationForm').addEventListener('submit',e=>{e.preventDefault();submitRegistration(e.target)});
 document.addEventListener('keydown',e=>{if((e.key==='/'||((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'))&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName)){e.preventDefault();openCommandPalette()}if(e.key==='Escape')$$('.modal-backdrop.open').forEach(m=>closeModal(m.id))});
 document.addEventListener('click',e=>{
  const p=e.target.closest('[data-profile]');if(p)openProfile(p.dataset.profile);
  const s=e.target.closest('[data-shop]');if(s)openShop(s.dataset.shop);
  const route=e.target.closest('[data-route]');if(route){e.preventDefault();routeHome()}
  const action=e.target.closest('[data-action]');if(action){const a=action.dataset.action;if(a==='open-login')openModal('loginModal');if(a==='open-registration'){populateRegistration();openModal('registrationModal')}if(a==='switch-registration'){closeModal('loginModal');openModal('registrationModal')}if(a==='open-courier-registration'){closeModal('loginModal');openModal('courierRegistrationModal')}if(a==='show-couriers')renderCouriers();if(a==='open-location')requestLocation();if(a==='show-map')$('.map-panel')?.scrollIntoView({behavior:'smooth',block:'center'})}
  const close=e.target.closest('[data-close]');if(close)closeModal(close.dataset.close);
  if(e.target.classList.contains('modal-backdrop'))closeModal(e.target.id);
  const demo=e.target.closest('[data-demo-role]');if(demo){if(demo.dataset.demoRole==='courier')window.location.href='./courier/?demo=1';else openPortal(demo.dataset.demoRole,demo.dataset.demoRole===requestedWorkspace?requestedWorkspaceTab:null)}
  const share=e.target.closest('[data-share-product]');if(share){e.preventDefault();shareProduct(share.dataset.shareShop,share.dataset.shareProduct)}
  const pay=e.target.closest('[data-pay-product]');if(pay){e.preventDefault();openPayment(pay.dataset.payShop,pay.dataset.payProduct)}
  const command=e.target.closest('[data-command-kind]');if(command)runCommand(command.dataset.commandKind,command.dataset.commandId);
  const tab=e.target.closest('[data-portal-tab]');if(tab){state.portalTab=tab.dataset.portalTab;renderPortal()}
  const quickTab=e.target.closest('[data-quick-tab]');if(quickTab){state.portalTab=quickTab.dataset.quickTab;renderPortal()}
  if(e.target.closest('[data-quick-action="storefront"]'))openShop('shop-1');
  const approve=e.target.closest('[data-approve]');if(approve){const a=ownerApplications.find(x=>x.id===Number(approve.dataset.approve));a.status='approved';showToast(`${a.business} approved — owner access enabled`,'badge-check');renderAdmin(state.portalTab)}
  const reject=e.target.closest('[data-reject]');if(reject){const a=ownerApplications.find(x=>x.id===Number(reject.dataset.reject));a.status='rejected';showToast(`${a.business} application rejected`,'x-circle');renderAdmin(state.portalTab)}
  const remove=e.target.closest('[data-remove-worker]');if(remove){workers.splice(Number(remove.dataset.removeWorker),1);showToast('Worker account deactivated','user-x');renderWorkers()}
  const confirmPayment=e.target.closest('[data-confirm-payment]');if(confirmPayment){const payment=customerPayments.find(p=>p.id===confirmPayment.dataset.confirmPayment),shop=shops[0],product=shop.products.find(p=>p.sku===payment?.sku);if(payment&&product){if(product.quantity<payment.baseQuantity){showToast('Insufficient stock. Restock before confirming.','triangle-alert');return}payment.status='confirmed';applyLocalMovement(shop.id,product.sku,-payment.baseQuantity);window.ZWOffline.enqueue('customer_order.review',{orderId:payment.id,approve:true,localShopId:shop.id,sku:payment.sku,baseQuantity:payment.baseQuantity},{role:'shop_owner'});showToast('Payment confirmed — sale, ledger and stock entries queued','book-check');renderPaymentConfirmations()}}
  const rejectPayment=e.target.closest('[data-reject-payment]');if(rejectPayment){const payment=customerPayments.find(p=>p.id===rejectPayment.dataset.rejectPayment);if(payment){payment.status='rejected';window.ZWOffline.enqueue('customer_order.review',{orderId:payment.id,approve:false,reason:'Payment details could not be verified'},{role:'shop_owner'});showToast('Payment rejected — stock was not changed','x-circle');renderPaymentConfirmations()}}
  const removeMethod=e.target.closest('[data-remove-payment-method]');if(removeMethod){const methods=paymentMethodsFor(shops[0]),method=methods[Number(removeMethod.dataset.removePaymentMethod)],index=paymentMethods.indexOf(method);if(index>=0)paymentMethods.splice(index,1);showToast('Payment method disabled','wallet-cards');renderPaymentSettings()}
  if(e.target.closest('#syncNowButton')){flushInventoryQueue();window.ZWOffline?.flush()}
  const retryAction=e.target.closest('[data-retry-action]');if(retryAction){window.ZWOffline?.retry(retryAction.dataset.retryAction).then(()=>{if(state.portalTab==='sync')renderSyncCenter()})}
  if(e.target.closest('#ownerLocate'))requestLocation();
 });
 document.addEventListener('submit',e=>{if(e.target.id==='workerForm'){e.preventDefault();if(workers.length>=7){showToast('This shop has reached the 7-worker limit','triangle-alert');return}const d=Object.fromEntries(new FormData(e.target)),shop=shops[0];workers.push({name:d.name,email:d.email,job:d.job,status:navigator.onLine?'Queued':'Offline queued'});window.ZWOffline.enqueue('worker.invite',{shopId:databaseShopId(shop),name:d.name,email:d.email,job:d.job.toLowerCase().replaceAll(' ','_')},{role:'shop_owner'});showToast(navigator.onLine?`Invitation queued for ${d.email}`:`Invitation saved offline for ${d.email}`,'send');renderWorkers()}});
 document.addEventListener('submit',e=>{if(e.target.id==='paymentMethodForm'){e.preventDefault();const d=Object.fromEntries(new FormData(e.target));paymentMethods.push({id:crypto.randomUUID(),shopId:shops[0].id,type:d.type,name:d.name,account:d.account,number:d.number,instructions:d.instructions});window.ZWOffline.enqueue('payment_method.save',{shopId:databaseShopId(shops[0]),method:{type:d.type,display_name:d.name,account_name:d.account,account_number:d.number,instructions:d.instructions}},{role:'shop_owner'});showToast('Payment method saved and queued','wallet-cards');renderPaymentSettings()}});
 document.addEventListener('submit',e=>{if(e.target.id==='customerPaymentForm'){e.preventDefault();const d=Object.fromEntries(new FormData(e.target)),shop=state.paymentShop,product=state.paymentProduct,quantity=Math.max(1,Number(d.quantity)||1),isCase=d.saleUnit==='case',baseQuantity=quantity*(isCase?product.caseSize:1),price=isCase?product.casePrice:product.price;if(baseQuantity>product.quantity){showToast('The requested quantity is no longer available','triangle-alert');return}if(d.delivery&&!d.deliveryAddress?.trim()){showToast('Enter a delivery address for bike delivery','map-pin');return}const orderId=crypto.randomUUID(),record={id:orderId,customer:d.name,phone:d.phone,product:product.name,sku:product.sku,unit:d.saleUnit,quantity,baseQuantity,amount:Number((price*quantity).toFixed(2)),reference:d.reference,delivery:Boolean(d.delivery),status:'pending'};customerPayments.unshift(record);window.ZWOffline.enqueue('customer_order.submit',{shopId:databaseShopId(shop),localShopId:shop.id,customerName:d.name,phone:d.phone,email:d.email||'',paymentMethodId:d.paymentMethod,reference:d.reference,items:[{sku:product.sku,quantity,sale_unit:d.saleUnit}],delivery:Boolean(d.delivery),deliveryAddress:d.deliveryAddress||null,deliveryCity:shop.city},{id:orderId,role:'public'});closeModal('paymentModal');e.target.reset();showToast(navigator.onLine?'Payment details sent for shop confirmation':'Payment details saved offline and will send when connected','shield-check')}});
 document.addEventListener('submit',e=>{if(e.target.id==='courierRegistrationForm'){e.preventDefault();const d=new FormData(e.target),proof=d.get('proof');if(!(proof instanceof File)||!proof.size){showToast('Upload courier identity and bicycle proof','file-warning');return}window.ZWOffline.enqueue('courier_application.submit',{name:d.get('name'),business:d.get('business'),email:d.get('email'),phone:d.get('phone'),nationalId:d.get('nationalId'),city:d.get('city'),bike:d.get('bike'),proof},{role:'applicant'});closeModal('courierRegistrationModal');e.target.reset();showToast(navigator.onLine?'Courier application queued for admin review':'Courier application saved offline','bike')}});
 document.addEventListener('submit',e=>{if(e.target.id==='saleForm'){e.preventDefault();const data=Object.fromEntries(new FormData(e.target)),shop=shops[0],product=shop.products.find(p=>p.sku===data.sku),packageQuantity=Number(data.quantity),isCase=data.saleUnit==='case',unitsPerCase=isCase?product?.caseSize||1:1,baseQuantity=packageQuantity*unitsPerCase,sellingPrice=isCase?product?.casePrice:product?.price;if(!product||packageQuantity<1||baseQuantity>product.quantity){showToast(isCase?'Not enough units to complete those cases':'Not enough singular units for this sale','triangle-alert');return}applyLocalMovement(shop.id,product.sku,-baseQuantity);const deviceId=localStorage.getItem('zwconnect-device-id')||crypto.randomUUID();localStorage.setItem('zwconnect-device-id',deviceId);window.ZWOffline.enqueue('sale.create',{shopId:databaseShopId(shop),localShopId:shop.id,items:[{sku:product.sku,quantity:packageQuantity,sale_unit:data.saleUnit,units_per_case:unitsPerCase,base_quantity:baseQuantity,unit_price:sellingPrice}],paymentMethod:data.payment,total:Number((sellingPrice*packageQuantity).toFixed(2)),soldAt:new Date().toISOString(),deviceId},{role:'worker'});const packageLabel=isCase?`${packageQuantity} ${packageQuantity===1?'case':'cases'} (${baseQuantity} units)`:`${packageQuantity} singular ${packageQuantity===1?'unit':'units'}`;showToast(navigator.onLine?`${packageLabel} sold — awaiting Supabase confirmation`:`${packageLabel} sold offline — queued safely`,'receipt-text');renderRegister()}});
 document.addEventListener('submit',e=>{if(e.target.id==='inventoryMovementForm'){e.preventDefault();const data=Object.fromEntries(new FormData(e.target));queueProductMovement('shop-1',data.sku,Number(data.delta),data.reason)}});
 document.addEventListener('change',e=>{if(e.target.id==='autoSyncToggle'){inventorySync.auto=e.target.checked;localStorage.setItem('zwconnect-auto-sync',String(inventorySync.auto));showToast(inventorySync.auto?'Automatic sync enabled':'Automatic sync paused','refresh-cw');if(inventorySync.auto&&navigator.onLine)flushInventoryQueue()}});
 document.addEventListener('change',e=>{if(e.target.matches('#saleProduct,#saleUnit'))updateSalePreview()});
 document.addEventListener('change',e=>{if(e.target.matches('#customerPaymentForm [name="saleUnit"]'))updateCustomerOrderTotal()});
 document.addEventListener('input',e=>{if(e.target.matches('#saleForm input[name="quantity"]'))updateSalePreview()});
 document.addEventListener('input',e=>{if(e.target.matches('#customerPaymentForm input[name="quantity"]'))updateCustomerOrderTotal()});
 const params=new URLSearchParams(location.search),sharedShop=params.get('shop'),sharedProduct=params.get('product'),hash=location.hash;
 requestedWorkspace=params.get('workspace');requestedWorkspaceTab=params.get('tab');
 if(requestedWorkspace==='admin'){location.replace('./admin/');return}
 if(requestedWorkspace==='courier'){location.replace('./courier/');return}
 if(['owner','worker'].includes(requestedWorkspace))openModal('loginModal');
 else if(params.get('customer')==='account')setTimeout(()=>document.querySelector('#customerAccountButton')?.click(),0);
 else if(params.get('customer')==='cart')setTimeout(()=>document.querySelector('#cartButton')?.click(),0);
 else if(sharedShop)openShop(sharedShop,sharedProduct||'');
 else if(hash==='#couriers')renderCouriers();
 else if(hash.startsWith('#profile/'))openProfile(hash.split('/')[1]);
 else if(hash.startsWith('#shop/'))openShop(hash.split('/')[1]);
});
